python - <<'PY'
from rdkit import Chem
for chir in ('@','@@'):
 s=f'[Si-]12(Oc3c(O1)c(Cl)c(Cl)c(Cl)c3Cl)(Oc4c(O2)c(Cl)c(Cl)c(Cl)c4Cl)O[C{chir}H](c5ccc(C)cc5)[P+](c6ccccc6)(c7ccccc7)c8ccccn8'
 m=Chem.MolFromSmiles(s)
 for a in m.GetAtoms():
  if a.GetSymbol()=='C' and a.GetChiralTag()!=Chem.ChiralType.CHI_UNSPECIFIED: print(chir, a.GetIdx(), a.GetProp('_CIPCode'))
PY
